#include "display.h"

// MD KIT: generated by tools/make_engine.py. The screen: the selected key's
// machine as the design draws one machine (art.h): its instrument on the left,
// its family's panel on the right, at that key's values (a held step's locks
// included), struck by each note.
namespace mdkit {
inline void display_reset(DisplayState& state) {
    state.hit.initialized = 0;
    state.hit.age = 1 << 20;
}

inline void display(DisplayState& state, const opxy::draw::Input& input, Frame& frame) {
    md::view::begin(frame, input);
    state.hit.update(input);
    const md::view::Moment moment = {state.hit.age, input.reduced_motion, state.hit.quiet};
    const u32 selected = input.model < kit::models ? input.model : 0;
    i32 own[8];
    kit::controls(selected, input.slots, own);
    for (u32 m = 0; m < kit::models; ++m)
        if (m != selected) md::rig::hide_all(frame, art::members, art::machines[m]);
    md::rig::draw(frame, art::parts, art::effects, art::members, art::machines[selected], own, moment,
                  selected == 9 || selected == 25 ? md::rig::shaker : md::rig::drum);
    switch (selected) {
    case 0: md::trx_bd::view(frame, own, moment); break;
    case 1: md::trx_sd::view(frame, own, moment); break;
    case 2: md::trx_xt::view(frame, own, moment); break;
    case 3: md::trx_cp::view(frame, own, moment); break;
    case 4: md::trx_rs::view(frame, own, moment); break;
    case 5: md::trx_cb::view(frame, own, moment); break;
    case 6: md::trx_ch::view(frame, own, moment); break;
    case 7: md::trx_oh::view(frame, own, moment); break;
    case 8: md::trx_cy::view(frame, own, moment); break;
    case 9: md::trx_ma::view(frame, own, moment); break;
    case 10: md::trx_cl::view(frame, own, moment); break;
    case 11: md::trx_xc::view(frame, own, moment); break;
    case 12: md::trx_b2::view(frame, own, moment); break;
    case 13: md::efm_bd::view(frame, own, moment); break;
    case 14: md::efm_sd::view(frame, own, moment); break;
    case 15: md::efm_xt::view(frame, own, moment); break;
    case 16: md::efm_cp::view(frame, own, moment); break;
    case 17: md::efm_rs::view(frame, own, moment); break;
    case 18: md::efm_cb::view(frame, own, moment); break;
    case 19: md::efm_hh::view(frame, own, moment); break;
    case 20: md::efm_cy::view(frame, own, moment); break;
    case 21: md::pi_bd::view(frame, own, moment); break;
    case 22: md::pi_sd::view(frame, own, moment); break;
    case 23: md::pi_mt::view(frame, own, moment); break;
    case 24: md::pi_ml::view(frame, own, moment); break;
    case 25: md::pi_ma::view(frame, own, moment); break;
    case 26: md::pi_rs::view(frame, own, moment); break;
    case 27: md::pi_rc::view(frame, own, moment); break;
    case 28: md::pi_cc::view(frame, own, moment); break;
    case 29: md::pi_hh::view(frame, own, moment); break;
    case 30: md::gnd_sn::view(frame, own, moment); break;
    case 31: md::gnd_ns::view(frame, own, moment); break;
    case 32: md::gnd_im::view(frame, own, moment); break;
    default: break;
    }
    // A slot the machine lacks shows nothing (an empty header keeps the stock value).
    for (u32 i = 0; i < 4; ++i)
        if (!kit::model[selected].labels[input.shown[i] & 7u][0])
            opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
}
}
